const item = $input.first().json;
const helpers = this.helpers;

const TREK_BASE = 'http://trek.household.svc.cluster.local:3000';
const TREK_TOKEN = $env.TREK_API_TOKEN;

function forwardedHeaders(extra) {
  return Object.assign(
    {
      'Authorization': 'Bearer ' + TREK_TOKEN,
      'X-Forwarded-Proto': 'https',
      'Host': '${TREK_SUBDOMAIN}.${SECRET_DOMAIN}',
    },
    extra || {}
  );
}

function parseMcpBody(bodyText) {
  const match = bodyText.match(/data:\s*(\{[\s\S]*\})/);
  const jsonText = match ? match[1] : bodyText;
  return JSON.parse(jsonText);
}

async function withRetry(fn, attempts, baseDelayMs) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (i < attempts - 1) {
        await new Promise(function (resolve) {
          setTimeout(resolve, baseDelayMs * Math.pow(2, i));
        });
      }
    }
  }
  throw lastErr;
}

async function mcpRpc(sessionId, method, params) {
  // Same retry scoping as Trek Resolve: only true request/response failures are
  // retried, never a response Trek actually sent back.
  const res = await withRetry(
    function () {
      return helpers.httpRequest({
        method: 'POST',
        url: TREK_BASE + '/mcp',
        headers: forwardedHeaders({
          'Content-Type': 'application/json',
          'Accept': 'application/json, text/event-stream',
          'Mcp-Session-Id': sessionId || undefined,
        }),
        body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: method, params: params || {} }),
        returnFullResponse: true,
      });
    },
    3,
    1000
  );
  return { parsed: parseMcpBody(String(res.body)), headers: res.headers };
}

async function mcpTool(sessionId, toolName, args) {
  const r = await mcpRpc(sessionId, 'tools/call', { name: toolName, arguments: args || {} });
  if (r.parsed.error) {
    throw new Error('Trek MCP error calling ' + toolName + ': ' + JSON.stringify(r.parsed.error));
  }
  const content = (r.parsed.result && r.parsed.result.content) || [];
  const textPart = content[content.length - 1];
  const raw = textPart ? textPart.text : '{}';
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error('Trek tool ' + toolName + ' returned a non-JSON response: ' + raw);
  }
  return parsed;
}

function httpErrorMessage(e) {
  const body = e && e.response && (e.response.body || e.response.data);
  if (body && typeof body === 'object' && body.error) return String(body.error);
  return (e && e.message) || String(e);
}

let extractionError = null;
let previewItems = [];
let previewWarnings = [];
let trips = [];

try {
  const initRes = await mcpRpc(null, 'initialize', {
    protocolVersion: '2024-11-05',
    capabilities: {},
    clientInfo: { name: 'n8n-trip-ingest', version: '1.0' },
  });
  const sessionId = initRes.headers['mcp-session-id'] || initRes.headers['Mcp-Session-Id'];
  const tripsData = await mcpTool(sessionId, 'list_trips', {});
  trips = tripsData.trips || [];
} catch (e) {
  extractionError = 'Could not reach Trek MCP: ' + (e.message || String(e));
}

if (!extractionError && trips.length === 0) {
  // The booking-import REST route is trip-scoped purely for TripAccessGuard - preview()
  // itself never reads anything about the trip - but there is no "no trip" escape hatch
  // in the guard chain, so a brand-new account with zero trips has nothing to point it at.
  extractionError = 'No trips exist in Trek yet - create one trip manually first so booking-import has a trip to preview against.';
}

if (!extractionError) {
  // Any accessible trip works as the URL param; it is never read by preview() itself.
  const scratchTripId = trips[0].id;
  try {
    const emailBuffer = await helpers.getBinaryDataBuffer(0, 'raw');
    const FormData = require('form-data');
    const form = new FormData();
    form.append('files', emailBuffer, { filename: 'email.eml', contentType: 'message/rfc822' });
    // fallback-on-empty: KDE Itinerary (structured tickets) runs first; the LLM only
    // fires for a file it returns nothing for. Safe to always pass even when the AI
    // Parsing addon has no model configured - preview() only calls the LLM when
    // aiAvailable() is true, so an unconfigured model just means kitinerary-only
    // results, not an error, unlike force-ai which 409s in that case.
    form.append('mode', 'fallback-on-empty');
    const previewRes = await helpers.httpRequest({
      method: 'POST',
      url: TREK_BASE + '/api/trips/' + scratchTripId + '/reservations/import/booking',
      headers: forwardedHeaders(),
      body: form,
      json: true,
      timeout: 240000,
    });
    previewItems = previewRes.items || [];
    previewWarnings = previewRes.warnings || [];
  } catch (e) {
    extractionError = 'Trek booking-import preview failed: ' + httpErrorMessage(e);
  }
}

return [
  {
    json: Object.assign({}, item, {
      trips: trips,
      previewItems: previewItems,
      previewWarnings: previewWarnings,
      extractionError: extractionError,
    }),
  },
];

const item = $input.first().json;
const previewItems = item.previewItems || [];
const previewWarnings = item.previewWarnings || [];
const extractionError = item.extractionError || null;
const trips = item.trips || [];
const helpers = this.helpers;

const TREK_BASE = 'http://trek.household.svc.cluster.local:3000';
const TREK_TOKEN = $env.TREK_API_TOKEN;

function forwardedHeaders(extra) {
  return Object.assign(
    {
      'Authorization': 'Bearer ' + TREK_TOKEN,
      'X-Forwarded-Proto': 'https',
      'Host': '${TREK_SUBDOMAIN}.${SECRET_DOMAIN}',
    },
    extra || {}
  );
}

function parseMcpBody(bodyText) {
  const match = bodyText.match(/data:\s*(\{[\s\S]*\})/);
  const jsonText = match ? match[1] : bodyText;
  return JSON.parse(jsonText);
}

async function withRetry(fn, attempts, baseDelayMs) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (i < attempts - 1) {
        await new Promise(function (resolve) {
          setTimeout(resolve, baseDelayMs * Math.pow(2, i));
        });
      }
    }
  }
  throw lastErr;
}

async function mcpRpc(sessionId, method, params) {
  const res = await withRetry(
    function () {
      return helpers.httpRequest({
        method: 'POST',
        url: TREK_BASE + '/mcp',
        headers: forwardedHeaders({
          'Content-Type': 'application/json',
          'Accept': 'application/json, text/event-stream',
          'Mcp-Session-Id': sessionId || undefined,
        }),
        body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: method, params: params || {} }),
        returnFullResponse: true,
      });
    },
    3,
    1000
  );
  return { parsed: parseMcpBody(String(res.body)), headers: res.headers };
}

async function mcpTool(sessionId, toolName, args) {
  const r = await mcpRpc(sessionId, 'tools/call', { name: toolName, arguments: args || {} });
  if (r.parsed.error) {
    throw new Error('Trek MCP error calling ' + toolName + ': ' + JSON.stringify(r.parsed.error));
  }
  const content = (r.parsed.result && r.parsed.result.content) || [];
  const textPart = content[content.length - 1];
  const raw = textPart ? textPart.text : '{}';
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error('Trek tool ' + toolName + ' returned a non-JSON response: ' + raw);
  }
  return parsed;
}

function httpErrorMessage(e) {
  const body = e && e.response && (e.response.body || e.response.data);
  if (body && typeof body === 'object' && body.error) return String(body.error);
  return (e && e.message) || String(e);
}

function toDate(s) {
  return s ? new Date(s) : null;
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  if (aStart == null || bStart == null) return false;
  const aE = aEnd != null ? aEnd : aStart;
  const bE = bEnd != null ? bEnd : bStart;
  return aStart <= bE && bStart <= aE;
}

function normalizeWords(s) {
  return (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(function (w) { return w.length > 2; });
}
function providerNamesRelated(a, b) {
  const wordsA = normalizeWords(a);
  const wordsB = normalizeWords(b);
  if (!wordsA.length || !wordsB.length) return false;
  return wordsA.some(function (w) { return wordsB.indexOf(w) !== -1; });
}

// Trek's own preview item already carries reservation_time/reservation_end_time for
// transport/generic bookings, or _accommodation.check_in/check_out for hotels - these
// helpers give the trip-matching and dedup logic below one date shape regardless of
// which one a given item actually has.
function itemStart(it) {
  if (it.reservation_time) return it.reservation_time;
  if (it._accommodation && it._accommodation.check_in) return it._accommodation.check_in;
  return null;
}
function itemEnd(it) {
  if (it.reservation_end_time) return it.reservation_end_time;
  if (it._accommodation && it._accommodation.check_out) return it._accommodation.check_out;
  return itemStart(it);
}
function destinationHint(it) {
  if (it.location) return it.location;
  if (it._venue && it._venue.name) return it._venue.name;
  if (Array.isArray(it.endpoints)) {
    const to = it.endpoints.find(function (e) { return e.role === 'to'; });
    if (to && to.name) return to.name;
  }
  return it.title;
}
function parseMeta(m) {
  if (!m) return {};
  if (typeof m === 'object') return m;
  try {
    return JSON.parse(m);
  } catch (e) {
    return {};
  }
}

let tripId = null;
let createdNewTrip = false;
let confirmedReservations = [];
let duplicateItems = [];
let trekError = null;

if (!extractionError && previewItems.length > 0) {
  try {
    const initRes = await mcpRpc(null, 'initialize', {
      protocolVersion: '2024-11-05',
      capabilities: {},
      clientInfo: { name: 'n8n-trip-ingest', version: '1.0' },
    });
    const sessionId = initRes.headers['mcp-session-id'] || initRes.headers['Mcp-Session-Id'];

    // One trip per email: match/create against the earliest start and latest end
    // across every parsed item, same window-matching Trek Resolve always used.
    const itemDates = previewItems
      .map(function (it) {
        return { start: toDate(itemStart(it)), end: toDate(itemEnd(it)) };
      })
      .filter(function (d) {
        return d.start;
      });
    const startDt = itemDates.length
      ? new Date(Math.min.apply(null, itemDates.map(function (d) { return d.start.getTime(); })))
      : null;
    const endDt = itemDates.length
      ? new Date(Math.max.apply(null, itemDates.map(function (d) { return (d.end || d.start).getTime(); })))
      : startDt;
    const startDateOnly = startDt ? startDt.toISOString().slice(0, 10) : null;
    const endDateOnly = endDt ? endDt.toISOString().slice(0, 10) : startDateOnly;

    let matchedTrip = null;
    if (startDt) {
      const windowMs = 3 * 24 * 60 * 60 * 1000;
      for (const t of trips) {
        const tStart = new Date(t.start_date + 'T00:00:00');
        const tEnd = new Date(t.end_date + 'T23:59:59');
        if (startDt.getTime() >= tStart.getTime() - windowMs && startDt.getTime() <= tEnd.getTime() + windowMs) {
          matchedTrip = t;
          break;
        }
      }
    }

    if (matchedTrip) {
      tripId = matchedTrip.id;
      const curStart = matchedTrip.start_date;
      const curEnd = matchedTrip.end_date;
      const newStart = startDateOnly && (!curStart || startDateOnly < curStart) ? startDateOnly : curStart;
      const newEnd = endDateOnly && (!curEnd || endDateOnly > curEnd) ? endDateOnly : curEnd;
      if (newStart !== curStart || newEnd !== curEnd) {
        // update_trip re-generates day rows for the new range, so confirm()'s own
        // resolveDayId finds an exact match instead of clamping to the nearest day.
        await mcpTool(sessionId, 'update_trip', { tripId: tripId, start_date: newStart, end_date: newEnd });
      }
    } else {
      const destName = destinationHint(previewItems[0]) || 'Trip';
      const createArgs = { title: 'Trip to ' + destName, currency: 'USD' };
      if (startDateOnly) createArgs.start_date = startDateOnly;
      if (endDateOnly) createArgs.end_date = endDateOnly;
      const created = await mcpTool(sessionId, 'create_trip', createArgs);
      tripId = created.trip ? created.trip.id : created.id;
      createdNewTrip = true;
    }

    const summary = await mcpTool(sessionId, 'get_trip_summary', { tripId: tripId });
    const days = summary.days || [];
    const dayDateById = {};
    days.forEach(function (d) {
      dayDateById[d.id] = d.date;
    });
    const existingReservations = summary.reservations || [];
    const existingAccommodations = summary.accommodations || [];

    const nonDuplicateItems = [];
    for (const it of previewItems) {
      const isHotel = it.type === 'hotel';
      let duplicateMatch = null;
      let duplicateMatchReason = null;

      if (it.confirmation_number) {
        duplicateMatch = isHotel
          ? existingAccommodations.find(function (a) { return a.confirmation === it.confirmation_number; })
              || existingReservations.find(function (r) { return r.type === 'hotel' && r.confirmation_number === it.confirmation_number; })
          : existingReservations.find(function (r) { return r.confirmation_number === it.confirmation_number; });
        if (duplicateMatch) duplicateMatchReason = 'matching confirmation number';
      }

      const itStartDt = toDate(itemStart(it));
      const itEndDt = toDate(itemEnd(it)) || itStartDt;

      if (!duplicateMatch && isHotel && itStartDt) {
        const startMs = itStartDt.getTime();
        const endMs = itEndDt.getTime();
        duplicateMatch = existingAccommodations.find(function (a) {
          if (!providerNamesRelated(it.title, a.place_name)) return false;
          const aStart = toDate(dayDateById[a.start_day_id]);
          if (!aStart) return false;
          const aEnd = toDate(dayDateById[a.end_day_id]) || aStart;
          return overlaps(startMs, endMs, aStart.getTime(), aEnd.getTime());
        }) || existingReservations.find(function (r) {
          if (r.type !== 'hotel') return false;
          if (!providerNamesRelated(it.title, r.title)) return false;
          const rStart = toDate(r.reservation_time);
          if (rStart) {
            const rEnd = toDate(r.reservation_end_time) || rStart;
            return overlaps(startMs, endMs, rStart.getTime(), rEnd.getTime());
          }
          const rDayDate = toDate(dayDateById[r.day_id]);
          if (!rDayDate) return false;
          const rDayEnd = toDate(dayDateById[r.end_day_id]) || rDayDate;
          return overlaps(startMs, endMs, rDayDate.getTime(), rDayEnd.getTime());
        });
        if (duplicateMatch) duplicateMatchReason = 'overlapping stay dates';
      }

      if (!duplicateMatch && !isHotel && itStartDt) {
        const startMs = itStartDt.getTime();
        const endMs = itEndDt.getTime();
        duplicateMatch = existingReservations.find(function (r) {
          if (r.type !== it.type) return false;
          if (!providerNamesRelated(it.title, r.title)) return false;
          const rStart = toDate(r.reservation_time);
          if (!rStart) return false;
          const rEnd = toDate(r.reservation_end_time) || rStart;
          return overlaps(startMs, endMs, rStart.getTime(), rEnd.getTime());
        });
        if (duplicateMatch) duplicateMatchReason = 'same type with overlapping dates';
      }

      if (duplicateMatch) {
        duplicateItems.push({ title: it.title, reason: duplicateMatchReason });
      } else {
        nonDuplicateItems.push(it);
      }
    }

    if (nonDuplicateItems.length > 0) {
      // confirm() is designed to receive exactly what preview() returned, unmodified -
      // so the surviving items are echoed back verbatim rather than reshaped. Trek's
      // own confirm() then does venue creation, accommodation linking, geocoding and a
      // properly currency-linked Costs entry (via reservation_id, which the public
      // create_budget_item MCP tool can't do) - all of it, no per-type branching needed
      // here any more.
      const confirmRes = await helpers.httpRequest({
        method: 'POST',
        url: TREK_BASE + '/api/trips/' + tripId + '/reservations/import/booking/confirm',
        headers: forwardedHeaders({ 'Content-Type': 'application/json' }),
        body: { items: nonDuplicateItems },
        json: true,
        timeout: 120000,
      });
      confirmedReservations = confirmRes.created || [];
    }
  } catch (e) {
    trekError = httpErrorMessage(e);
  }
}

const execRef = 'n8n-exec-' + ($execution && $execution.id ? $execution.id : 'unknown');

let notifySubject;
let notifyText;
if (extractionError) {
  notifySubject = 'Could not process trip email: ' + (item.subject || 'no subject');
  notifyText =
    'I could not process this email automatically.\n\n' +
    'Error: ' + extractionError + '\n\n' +
    'Original subject: ' + (item.subject || 'n/a') + '\n' +
    'From: ' + (item.mimeFrom || 'n/a') + '\n\n' +
    'Please add this to Trek manually if it is a real booking.\n\n' +
    'Ref: ' + execRef;
} else if (previewItems.length === 0) {
  notifySubject = 'No booking found: ' + (item.subject || 'no subject');
  notifyText =
    'Trek could not find a reservation in this email.\n\n' +
    'Subject: ' + (item.subject || 'n/a') + '\n' +
    'From: ' + (item.mimeFrom || 'n/a') +
    (previewWarnings.length ? '\n\nDetails: ' + previewWarnings.join('; ') : '') +
    '\n\nIf this was a real booking, add it to Trek manually.\n\n' +
    'Ref: ' + execRef;
} else if (trekError) {
  notifySubject = 'Trek add failed: ' + (previewItems[0].title || 'Booking');
  notifyText =
    'I could not add this to Trek automatically - please add it manually.\n\n' +
    'Error: ' + trekError + '\n' +
    'Items parsed: ' + previewItems.map(function (it) { return it.title; }).join(', ') +
    (previewWarnings.length ? '\n\nWarning: ' + previewWarnings.join('; ') : '') +
    '\n\nRef: ' + execRef;
} else {
  const lines = [];
  lines.push(
    (createdNewTrip ? 'Created a new trip and added ' : 'Added ') +
      confirmedReservations.length + ' booking(s)' +
      (createdNewTrip ? '.' : ' to an existing trip.')
  );
  if (duplicateItems.length > 0) {
    lines.push(
      duplicateItems.length + ' item(s) were already in Trek and skipped: ' +
        duplicateItems.map(function (d) { return d.title + ' (' + d.reason + ')'; }).join('; ')
    );
  }
  lines.push('Trip: https://${TREK_SUBDOMAIN}.${SECRET_DOMAIN}/trips/' + tripId);
  confirmedReservations.forEach(function (r) {
    const meta = parseMeta(r.metadata);
    const price = meta.price != null ? Number(meta.price) : null;
    lines.push(
      '- ' + r.title +
        (r.confirmation_number ? ' (' + r.confirmation_number + ')' : '') +
        (price ? ' - ' + price.toFixed(2) + ' ' + (meta.priceCurrency || '') : '')
    );
  });
  if (previewWarnings.length) lines.push('\nWarnings: ' + previewWarnings.join('; '));
  notifySubject = 'Added to Trek: ' + confirmedReservations.length + ' booking(s)' +
    (previewItems.length === 1 ? ' - ' + previewItems[0].title : '');
  notifyText = lines.join('\n') + '\n\nRef: ' + execRef;
}

return [
  {
    json: Object.assign({}, item, {
      trekTripId: tripId,
      trekCreatedNewTrip: createdNewTrip,
      trekConfirmedCount: confirmedReservations.length,
      trekDuplicateItems: duplicateItems,
      trekError: trekError,
      extractionError: extractionError,
      notifySubject: notifySubject,
      notifyText: notifyText,
    }),
  },
];
